// lore_part_nosferatu_b.js — Nosferatu batch 2 (+25, ids nosferatu21..45). DO NOT EDIT merged output; edit this file.
window.LORE_PART_NOSFERATU_B = { clans: [nosferatuB()] };
function nosferatuB() {
  function char(id, name, alias, gen, era, city, place, threat, lore_md) {
    return { id: id, name: name, alias: alias, gen: gen, era: era, location: { city: city, place: place }, threat: threat, lore_md: lore_md, photo: "assets/img/char_" + id + ".png" };
  }
  return {
    id: "nosferatu",
    name: "Nosferatu",
    nickname: "The Sewer Rats",
    disciplines: ["Animalism", "Obfuscate", "Potence"],
    weakness: "Every Nosferatu wears the curse on the skin: permanent, inhuman ugliness that no amount of feeding removes.",
    lore_md: "Batch 2 of the registry. These files arrived crumpled, water-stained, some typed on paper that should not exist. Read them anyway. The rats wrote them and the rats do not waste words.",
    chars: [
      char("nosferatu21", "Pestilentia", "THE PLAGUE KEEPING WIDOW", 5, "Roman Empire to present", "Rome", "Cloaca Maxima outfall", "high",
        "She was a physician before the Embrace and a worse thing after. Pestilentia has kept a continuous ledger of every fever that passed through Rome for eighteen centuries, and the ledger is written in rat-tooth marks on vellum. She claims she can predict the next plague two years out by counting which rat clans emigrate first. The Second Inquisition has raided the Cloaca twice and found only cold air, warm water, and a message in bone-chalk: MIND YOUR OWN BREATHING. She trades prophecy for blood, never for money. Asking her the wrong question costs a memory."),
      char("nosferatu22", "Grist", "THE SALT MINER", 9, "Embraced 1921", "Detroit", "Detroit salt mine level 1,150 ft", "mid",
        "Grist tunnels with a pick because machines fail and teeth do not. He maps the salt veins under Detroit the way other Kindred map city blocks, and his maps are never wrong. He sells three kinds of passage: fast, slow, and secret. Grist heard the network exists because a tremor in the salt told him, years before the first operator logged in. His commentary arrives typed on mine timetables. He wants one thing: nobody breathes loud in his tunnels. The salt remembers who disturbs it."),
      char("nosferatu23", "Amara Trench", "THE ESTERO LISTENER", 10, "Embraced 2004", "Manila", "Estero de San Miguel flood channel", "low",
        "Amara was a street child of the estero before the curse gave her a face worth hiding and ears worth everything. She catalogues the water: which siphons flood on which tide, which dry season exposes which door. Her wire posts read like lullabies and land like ambushes. She once held an entire Sabbat pack in a culvert for six hours with two buckets, a pump, and the tide table. She asks visitors to bring her a jar of clean water from wherever they came. She says she is collecting the world."),
      char("nosferatu24", "The Sexton", "THE GRAVEYARD SHIFT", 8, "Embraced 1887", "London", "Highgate Cemetery catacombs", "mid",
        "He still wears the sexton coat from 1887 and still carries keys to every crypt in north London, including three that were sealed by court order. The Sexton brokers the oldest favor economy in the city: a burial arranged, a grave unarranged, a coffin moved from where it was to where it should have been. His files in SchreckNET are tidy, dated, and utterly wrong, which is how operators know he files them himself. He is not malicious. He is simply paid in secrets and spends them recklessly."),
      char("nosferatu25", "Ratu Selatan", "THE FLOOD QUEEN OF THE SOUTH", 7, "Embraced 1740s", "Jakarta", "Ciliwung flood siphons", "mid",
        "Half the Jakarta underworld pays her homage and the other half does not know she exists, which is the way she prefers it. Ratu Selatan owns the tide: every pump station, every siphon gate, every flooded basement that drowns on schedule. Her court is a pump house, her throne a gantry, her decrees spoken in three languages at once so that eavesdroppers only ever understand one. She is courteous, unfailingly, until she is not. The network keeps her channel marked TIDE-LAW. Nobody argues with TIDE-LAW."),
      char("nosferatu26", "Vasco the Gutterpriest", "THE ABSOLVER OF DRAINS", 8, "Embraced 1637", "Lisbon", "Bairro Alto medieval cisterns", "mid",
        "Vasco believes the curse is a confession the body is forced to make, and he has turned his cisterns into a church for the confession of others. Kindred come down to be heard, to say the thing they cannot say above. He charges nothing. He remembers everything. His absolutions are valid in no rite and real anyway. The Inquisition burned a confessional network once; they think they got him. The network knows better: his listening posts simply moved under the ruins of the old ones, where the priests were."),
      char("nosferatu27", "Ironjaw Magda", "THE TUNNEL CRUSHER", 7, "Embraced 1871", "Gdansk", "WWII fortress tunnels, Westerplatte underlevels", "high",
        "Magda broke her own jaw in a blast and wired it back with coffin nails. It never healed right. It got stronger. She reads war like other Kindred read ledgers: who dug, who died, who sealed what and why. Her territory is the war archive under the Baltic coast, and she guards it with a fury that has ended two packs and one archon. She does not sell passage. She grants it, in person, by looking at you with the eyes of something that has buried every century it ever met."),
      char("nosferatu28", "Ozias Bell", "THE PUMP STATION PROPHET", 10, "Embraced 1999", "New Orleans", "Drainage Pump Station 6", "low",
        "Ozias was embraced the night the new century flooded the old one and has treated the whole city as a machine to outwit ever since. He knows the pumps by their vibration signatures and the neighborhoods by their silences. His wire dispatches arrive as single sentences, always true, always late enough to be useless to hunters and early enough to save Kindred. He wants nothing, which in the registry is the mark of either a saint or a deep-cover operator. Nobody has decided."),
      char("nosferatu29", "Kirill Shcherbaty", "THE DEEP LINE HERMIT", 9, "Embraced 1985", "Kyiv", "Deep-level metro line, unfinished station", "mid",
        "Kirill lives in the station that was never opened, on the line that was never named, and he would like to keep it that way. He traded air rights to four factions and allegiance to none. What he sells is silence: trains that do not stop, sensors that read zero, patrols that route around. His one obsession is the humming in the deep rock, which he says has a rhythm now, and the rhythm is counting. Operators flagged it hysteria. Then three of them checked the seismographs. Flag: COUNTING-HUM, active."),
      char("nosferatu30", "Sister Umbrage", "THE CONVENT OF PIPES", 8, "Embraced 1601", "Quito", "Colonial-era drainage vaults, Old Town", "mid",
        "Sister Umbrage runs a chapel of one under the oldest city block in Quito, fed by a hundred colonial pipes she has spent four centuries memorizing. She hears the city through the walls the way abbots hear choirs. Her counsel is expensive and paid in honesty, extracted by making the supplicant speak into a pipe that carries to a room she never describes. Two princes owe her their seats. One paid in a name. The name is redacted in every copy of her file. It is not redacted because it is dangerous. It is redacted because she asked."),
      char("nosferatu31", "The Leech of Kowloon", "THE WALLS REMEMBER", 6, "Embraced 1898", "Hong Kong", "Substructure of the former Walled City", "high",
        "The Walled City was demolished in 1994. Its foundations were not. The Leech stayed, in the concrete roots of the densest city block ever built, in corridors that no survey has ever drawn correctly. He was a surveyor. Now he is the survey. Every blueprint of that ground is wrong in a way that keeps a hunter alive exactly long enough to stop hunting. He trades accurate maps for names of everyone who tries to survey the site. The SI sent drones. The drones returned to a different Hong Kong."),
      char("nosferatu32", "Perpetua Nyx", "THE CULVERT CHORISTER", 9, "Embraced 1903", "Naples", "Cumana culvert gallery, Fuorigrotta", "mid",
        "Perpetua mapped the acoustics of an entire city by listening in culverts, and she will sing the map to you in one sitting. Singers who learn the chorus can navigate Naples blindfolded; listeners who learn the counterpoint can hear a heartbeat three districts away. The Camarilla leases her ears. The Sabbat once tried to lease her silence. The Sabbat no longer has a Naples chapter. Her file notes, in careful operator hand: do not request the third song. The third song is for her sire, and he is listening too."),
      char("nosferatu33", "Wernher Kegel", "THE BUNKER ACCOUNTANT", 8, "Embraced 1946", "Berlin", "Gesundbrunnen bunker levels", "mid",
        "Kegel survived the war in the archives of a war, and it changed his understanding of paperwork permanently. He believes every atrocity is filed somewhere, and he has spent eighty years finding the somebodies. His bunker holds four kilometers of shelving: requisitions, rolls, manifests. Nothing valuable. Everything damning. Princes pay him to lose their files and archons pay more to find them. He always loses, never loses, and never forgets. His ledger of who asked for what is the most dangerous single document in the German registry."),
      char("nosferatu34", "Sela Ochoa", "THE CANAL GARDENER", 10, "Embraced 2011", "Bogota", "Canal interceptor, Barrio San Luis", "low",
        "Sela grows things in the dark: mushrooms that digest evidence, lichens that record sound in their cells, a strain of moss that glows where blood has passed. Her garden is the best forensic instrument on the network and she does not know what forensics means. She simply watches, and the garden tells her, and she posts what it says. The Medellin file moved through her channel for three weeks before anyone claimed it. Read the cannibalism file and note the timeline. Note where the first warning came from."),
      char("nosferatu35", "Bartek the Hollow", "THE SEWER FORT ROOFRAT", 9, "Embraced 1979", "Warsaw", "Fortified junction, Vistula collector 3", "mid",
        "Bartek fortified a sewer junction into a keep: welded doors, kill corridors, water curtains, one drawbridge made of rebar and spite. He fought the Sabbat for it in 1994, the SI for it in 2021, and two Nosferatu elders for it because they forgot to ask. He flies no banner. He answers every intrusion with the same typed line: WRONG SEWER. Operators use his keep as the safest waypoint between Prague and Vilnius. The toll is one true story he has not heard. He has heard almost all of them."),
      char("nosferatu36", "Muirenn Dubh", "THE BOG INDEX", 8, "Embraced 1567", "Dublin", "Medieval bog drains under Kilmainham", "mid",
        "Muirenn keeps the only complete genealogy of Irish Kindred, from the first invasion to the Troubles, in her head and in peat. Peat preserves; so does she. Her index answers three questions with certainty: who sired whom, who died where, and who was buried standing. The third answer is always correct and always means something went wrong in the line. She speaks slowly, records nothing written, and has never once been wrong in four hundred and fifty years. Operators who doubt her are invited to check the bogs themselves."),
      char("nosferatu37", "Zahid Al-Nafis", "THE CANAL EMBALMER", 7, "Embraced 1349", "Cairo", "Mortuary canal dock, City of the Dead", "mid",
        "Zahid prepares the dead of the City of the Dead for burial and the unliving for very long journeys. He is the treaty-post between the Hecata and every Cairo faction, the neutral hand that closes eyes on both sides. His neutrality is absolute, his tariffs fixed, his receipts famous: a wax seal in the shape of an open eye. Fake his seal once and the Hecata, the court, and the Brotherhood hunt you together. His file smells like spices. Operators complain the scans keep coming out warm."),
      char("nosferatu38", "Old Teeth", "THE THING UNDER THE ICE", null, "Predates registry records", "Kathmandu region", "Glacial melt tunnels, uncharted", "high",
        "There is a file that predates the registry. It describes a Nosferatu of impossible age in the melt tunnels under the Himalaya, with teeth that grew so long they were filed and used as currency by the villagers of three valleys. Every century a survey party goes up. Every century the file adds a line. The current line reads: HE IS STILL TRADING. The network does not go there. The network asks politely that you not go there either. If you must, take nothing, eat nothing, and bring your own teeth."),
      char("nosferatu39", "Marina Voronova", "THE COLLECTOR CAT", 9, "Embraced 1912", "Saint Petersburg", "Granite collector, Neva undercrossing", "mid",
        "Marina names every rat in her collector and keeps a census that reads like a novel. Her rat-ledger has caught three infiltrators who fooled cameras, four who fooled blood tests, and one who fooled another Nosferatu. The rats do not lie about smell. She teaches the deep game to neonates of the clan: sit still, listen twice, smell once, speak never. Her dispatches are signed with a pawprint stamp she refills with real ash. The registry rates her channel the most reliable in the Baltic. She rates it adequate."),
      char("nosferatu40", "Uncle Craw", "THE STORMWATER UNCLE", 7, "Embraced 1885", "Sydney", "Stormwater canals, Pyrmont outfall", "mid",
        "Uncle Craw adopted the clan. All of it. Every neonate that reaches Sydney without a name gets a bed, a ration, and a term of instruction under the outfall, and leaves with a name. He asks nothing except that each graduate help one stranger up the same ladder. The clan politics of three continents have a Craw line in them now, and none of them report to him. He just remembers. When the SI burned a warren in 2022, eleven alumni arrived within a night, from eleven countries. The hunter files call it a swarm. It was a family."),
      char("nosferatu41", "Delia Fane", "THE VOID LISTENER", 10, "Embraced 2009", "Glasgow", "The Void, sub-basement of the old coverset", "low",
        "Under one demolished Glasgow block there is a room with no outside walls, and Delia lives in it. The acoustic there is perfect. She says she can hear the sewers of four cities through the ground, which the registry once filed as poetry until she predicted three collapses and one murder to the minute. Her posts arrive in lowercase, unsolicited, at 04:00 local time, always titled same night, different dark. She wants pictures of the moon. Send one occasionally. It costs nothing and she keeps every single one."),
      char("nosferatu42", "The Rat King Envoy", "COURIER OF THE WARRENS", null, "Unknown", "Unknown", "The deep warrens", "high",
        "Somebody delivers sealed letters between warrens that no operator can trace, along tunnels that appear on no map, on a schedule that matches no calendar. The network calls the sender the Rat King Envoy. The letters are always opened correctly, always delivered intact, and never have a return address. Three elders have tried to intercept one. The letters arrived anyway, on time, with a polite note about the attempt. Protocol stands: accept the delivery, log the seal, ask nothing. The warrens were old before the clan had a name."),
      char("nosferatu43", "Piotr Hlava", "THE OSSUARY PLUMBER", 8, "Embraced 1741", "Prague", "Plague-ossuary cistern, Old Town sublevel", "mid",
        "Piotr maintains the water supply of a city that does not know him, in drains built by people who never knew why they got sick. His work is sacred to him: flow is life, blockage is plague, and he has ended two epidemics by re-routing a single pipe. He trades water knowledge the way elders trade blood. The registry lists his channel as PIPE-BLESSING. His one rule is absolute: nobody dies dirty in his drains. Even enemies get washed before the end. He has buried four hunters respectfully and filed their tools neatly."),
      char("nosferatu44", "Aza of the Third Cistern", "THE MEDINA MOTH", 10, "Embraced 2015", "Tunis", "Hafsid-era cistern, medina third ring", "low",
        "Aza was a scholar of lost water systems and remains one, just wetter. She restores dead cisterns for the joy of hearing them fill, and her restored cisterns are the quietest meeting rooms on the African network: no bugging, no leakage, no history that anyone else can read. She will host any faction that leaves weapons at the second ring. Her price is stories about water, real ones, from anywhere. Her archive of water-stories is the strangest intelligence library in the registry and has cracked three codes by context alone."),
      char("nosferatu45", "The Flenser", "THE UNNAMED HARVEST", 6, "Unknown", "Unknown", "Abandoned slaughterhouse sublevel, city unknown", "high",
        "The Flenser appears in seventeen city files across four continents, always in the sublevel of a decommissioned slaughterhouse, always within a week of a district going quiet. Nobody has a portrait. The cameras that catch the corridor catch a smear with shoulders. What is known: it takes exactly one Kindred per city, never an elder, never a child of the clan, and the district functions normally afterward but rats emigrate. Standing network directive: DO NOT VOLUNTEER. DO NOT DEDUCE ALOUD. If the Flenser is in your city, the warren already knows."),
    ],
  };
}
